function validate([parent, s]) {
  if (!Array.isArray(parent) || parent.length < 1 || parent.length > 100000) return 'parent needs 1 to 10^5 entries.';
  if (typeof s !== 'string' || s.length !== parent.length) return 's must have exactly one letter per node.';
  if (!/^[a-z]*$/.test(s)) return 's may contain only lowercase letters.';
  const n = parent.length;
  if (parent[0] !== -1) return 'parent[0] must be -1 (node 0 is the root).';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    const p = parent[i];
    if (!Number.isInteger(p) || p < 0 || p >= n || p === i) return 'Each parent[i] for i >= 1 must be another node from 0 to n - 1.';
    children[p].push(i);
  }
  const queue = [0];
  for (let q = 0; q < queue.length; q++) for (const c of children[queue[q]]) queue.push(c);
  if (queue.length !== n) return 'parent must describe one tree rooted at node 0 (no cycles).';
  return null;
}

