function findSubtreeSizes(parent, s) {
  const n = parent.length;
  const children = Array.from({ length: n }, () => []);
  for (let node = 1; node < n; node++) {
    children[parent[node]].push(node);
  }
  const answer = new Array(n).fill(1);
  const closest = new Map();

  function dfs(node) {
    const letter = s[node];
    const ancestor = closest.get(letter);
    closest.set(letter, node);
    for (const child of children[node]) {
      dfs(child);
    }
    if (ancestor === undefined) {
      closest.delete(letter);
    } else {
      closest.set(letter, ancestor);
    }
    if (node !== 0) {
      const newParent = ancestor === undefined ? parent[node] : ancestor;
      answer[newParent] += answer[node];
    }
  }

  dfs(0);
  return answer;
}

