function findSubtreeSizes(parent, s) {
  // Walk up from every node to find its new parent, then count each node once for every final ancestor.
  const n = parent.length;
  const finalParent = parent.slice();
  for (let x = 1; x < n; x++) {
    for (let y = parent[x]; y !== -1; y = parent[y]) {
      if (s[y] === s[x]) {
        finalParent[x] = y;
        break;
      }
    }
  }
  const sizes = new Array(n).fill(0);
  for (let x = 0; x < n; x++) {
    for (let y = x; y !== -1; y = finalParent[y]) sizes[y]++;
  }
  return sizes;
}

