function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 9);
  const shape = Math.floor(rand() * 4);
  // Grow a tree in which every node hangs below an earlier one, then give nodes 1..n-1 random numbers.
  const grown = [-1];
  for (let i = 1; i < n; i++) {
    if (shape === 0) grown.push(i - 1);
    else if (shape === 1) grown.push(rand() < 0.7 ? 0 : Math.floor(rand() * i));
    else if (shape === 2) grown.push(Math.max(0, i - 1 - Math.floor(rand() * 3)));
    else grown.push(Math.floor(rand() * i));
  }
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rest[i], rest[j]] = [rest[j], rest[i]];
  }
  const label = [0, ...rest];
  const parent = new Array(n);
  parent[0] = -1;
  for (let i = 1; i < n; i++) parent[label[i]] = label[grown[i]];
  const letters = large ? [2, 5, 26][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 3);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [parent, s];
}
